    src_dwords[5] = rd(src0_base, lane, 5);
    uint8_t vals[32];
    util::unpack_6bit(src_dwords, vals);
    wr(vdst_base, lane, 0,
       std::bit_cast<uint32_t>(
           static_cast<float>(static_cast<double>(util::fp6_e2m3_to_f32(vals[0])) * scale)));
